from __future__ import annotations

DASHBOARD_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>PCP Live Workflow Dashboard</title>
<style>
:root{color-scheme:dark;--bg:#080b12;--panel:#101620;--panel2:#151d29;--border:#243044;--text:#edf2f7;--muted:#91a0b5;--accent:#6ee7b7;--blue:#60a5fa;--amber:#fbbf24;--red:#fb7185;--purple:#c084fc}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% -10%,#17233a 0,transparent 34%),var(--bg);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--text)}a{color:#93c5fd;text-decoration:none}.wrap{max-width:1480px;margin:0 auto;padding:26px}.top{display:flex;gap:18px;align-items:center;justify-content:space-between;margin-bottom:22px}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.title{font-size:27px;font-weight:750;letter-spacing:-.025em;margin:2px 0}.sub{color:var(--muted)}.pill{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border:1px solid var(--border);border-radius:999px;background:#0d131d;color:var(--muted);font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--accent);box-shadow:0 0 14px var(--accent)}.grid{display:grid;gap:14px}.summary{grid-template-columns:repeat(6,minmax(0,1fr));margin-bottom:14px}.card{background:linear-gradient(180deg,rgba(21,29,41,.93),rgba(12,17,26,.95));border:1px solid var(--border);border-radius:15px;padding:16px;box-shadow:0 15px 50px rgba(0,0,0,.18)}.k{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.09em;font-weight:750}.v{font-size:27px;font-weight:760;margin-top:6px;letter-spacing:-.03em}.small{font-size:12px;color:var(--muted);margin-top:3px}.main{grid-template-columns:minmax(0,1.72fr) minmax(340px,.78fr);align-items:start}.section{margin-bottom:14px}.section-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:14px}.section-title{font-size:16px;font-weight:720}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}.status{display:inline-flex;border-radius:999px;padding:4px 8px;font-size:11px;font-weight:760;text-transform:uppercase;letter-spacing:.06em;border:1px solid}.s-running,.s-executing,.s-active,.s-planning,.s-routing,.s-verifying,.s-evaluating,.s-delivering{color:#93c5fd;border-color:#31598d;background:#102139}.s-completed,.s-sent{color:#86efac;border-color:#256548;background:#0e2b20}.s-awaiting_merge,.s-waiting_merge,.s-waiting_human{color:#fcd34d;border-color:#735b18;background:#2d250c}.s-blocked,.s-failed,.s-cancelled,.s-interrupted{color:#fda4af;border-color:#7f3342;background:#30131a}.s-pending,.s-queued{color:#c4b5fd;border-color:#5a4684;background:#211936}.pipeline{display:flex;gap:8px;overflow:auto;padding-bottom:4px}.step{min-width:215px;flex:1;border:1px solid var(--border);border-radius:12px;padding:12px;background:#0b111a}.step.current{border-color:#3f6fa8;box-shadow:inset 0 0 0 1px #31598d}.step .num{font-size:10px;color:var(--muted)}.step .name{font-weight:670;margin:5px 0 9px;word-break:break-word}.step .mode{font-size:11px;color:var(--muted)}.metrics{grid-template-columns:repeat(4,minmax(0,1fr))}.metric{border:1px solid var(--border);border-radius:12px;padding:13px;background:#0b111a}.metric .mv{font-size:20px;font-weight:720;margin-top:5px}.bar{height:7px;background:#202b3c;border-radius:9px;overflow:hidden;margin-top:9px}.fill{height:100%;background:linear-gradient(90deg,var(--blue),var(--accent));border-radius:9px}.fill.warn{background:linear-gradient(90deg,var(--amber),#fb923c)}.fill.danger{background:linear-gradient(90deg,#fb7185,#ef4444)}.model-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.model{border:1px solid var(--border);background:#0b111a;border-radius:11px;padding:12px}.model.active{border-color:#3e8c73}.model .role{text-transform:uppercase;font-size:10px;letter-spacing:.1em;color:var(--muted);font-weight:760}.model .mid{font-weight:720;margin-top:5px}.model .prov{font-size:12px;color:var(--muted);margin-top:3px}.token-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.token-box{background:#0b111a;border:1px solid var(--border);border-radius:12px;padding:13px}.token-big{font-size:22px;font-weight:730}.token-meta{font-size:11px;color:var(--muted);margin-top:3px}.activity{margin-top:10px;max-height:520px;overflow:auto}.activity-item{position:relative;margin-left:7px;padding:0 0 16px 20px;border-left:1px solid #2a394d}.activity-item:last-child{padding-bottom:2px}.activity-dot{position:absolute;left:-5px;top:4px;width:9px;height:9px;border-radius:50%;background:var(--blue);box-shadow:0 0 0 3px #101620}.activity-dot.success{background:var(--accent)}.activity-dot.warning{background:var(--amber)}.activity-dot.error{background:var(--red)}.activity-message{font-weight:680}.activity-time{font-size:10px;color:var(--muted);margin-top:2px}.activity-detail{font-size:11px;color:#aebacc;margin-top:4px}.quota-card{margin-top:10px;padding:11px;border:1px solid var(--border);border-radius:11px;background:#0b111a}.quota-label{font-weight:680}.quota-value{color:var(--amber);font-weight:760;margin-top:5px}.quota-models{font-size:10px;color:var(--muted);margin-top:5px;word-break:break-word}.alert{padding:11px 0;border-bottom:1px solid #1c2737}.alert:last-child{border-bottom:0}.alert-top{display:flex;justify-content:space-between;gap:10px}.sev{font-size:10px;text-transform:uppercase;letter-spacing:.08em;font-weight:780}.sev-error{color:var(--red)}.sev-warning{color:var(--amber)}.sev-success{color:var(--accent)}.alert p{margin:5px 0;color:#c8d2df;font-size:12px}.empty{color:var(--muted);padding:18px 4px;text-align:center}.login{position:fixed;inset:0;background:rgba(3,6,12,.88);backdrop-filter:blur(12px);display:none;align-items:center;justify-content:center;z-index:20}.login.show{display:flex}.login-box{width:min(420px,calc(100vw - 34px));background:#0f1622;border:1px solid var(--border);border-radius:17px;padding:24px}.login-box h2{margin:2px 0 6px}.login-box input{width:100%;margin:16px 0 10px;background:#080d15;border:1px solid #334158;color:white;border-radius:10px;padding:12px;font:inherit}.login-box button{border:0;border-radius:10px;padding:11px 14px;background:#e7f7f1;color:#062219;font-weight:760;cursor:pointer}.err{color:#fda4af;font-size:12px;min-height:18px;margin-top:8px}.foot{font-size:11px;color:#718096;margin-top:14px}.select{background:#0a1018;border:1px solid var(--border);color:var(--text);border-radius:9px;padding:7px 9px;max-width:320px}@media(max-width:1050px){.summary{grid-template-columns:repeat(3,1fr)}.main{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.wrap{padding:15px}.summary{grid-template-columns:repeat(2,1fr)}.metrics,.model-grid,.token-row{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.title{font-size:23px}}
</style>
</head>
<body>
<div class="login" id="login"><div class="login-box"><div class="eyebrow">Read-only access</div><h2>Workflow dashboard</h2><div class="sub">Enter DASHBOARD_READ_TOKEN. It is exchanged for an HttpOnly session cookie and is not stored in JavaScript.</div><input id="token" type="password" autocomplete="current-password" placeholder="Dashboard read token" /><button id="loginBtn">Open dashboard</button><div class="err" id="loginErr"></div></div></div>
<div class="wrap"><div class="top"><div><div class="eyebrow">Personal Coding Platform</div><div class="title">Live Workflow Dashboard</div><div class="sub" id="subtitle">Connecting…</div></div><div class="pill"><span class="dot"></span><span id="connection">polling every 3s</span></div></div><div class="grid summary" id="summary"></div><div class="grid main"><div><section class="card section"><div class="section-head"><div><div class="section-title">Execution plan</div><div class="small mono" id="planMeta">—</div></div><select id="planSelect" class="select"></select></div><div id="pipeline" class="pipeline"></div></section><section class="card section"><div class="section-head"><div><div class="section-title">Current job telemetry</div><div class="small" id="jobMeta">No active job</div></div><div id="jobStatus"></div></div><div class="grid metrics" id="metrics"></div></section><section class="card section"><div class="section-head"><div><div class="section-title">Model assignment</div><div class="small">Analysis depth is Router policy; Reasoning is the explicit effort sent to Codex when applicable.</div></div><div id="profile"></div></div><div class="model-grid" id="models"></div></section><section class="card section"><div class="section-head"><div><div class="section-title">Token budget</div><div class="small">Input usage is cache-aware. Last-attempt gross/cached input is shown when the adapter reported it.</div></div></div><div class="token-row" id="tokens"></div></section><section class="card section"><div class="section-head"><div><div class="section-title">Job budget remaining</div><div class="small">Exact remaining limits from the durable Runtime budget.</div></div></div><div class="grid metrics" id="remaining"></div></section></div><aside><section class="card section"><div class="section-title">Live activity</div><div class="small">Durable, sanitized Runtime events · polling every 3s</div><div id="activity" class="activity"></div></section><section class="card section"><div class="section-title">Provider quota remaining</div><div class="small">Account-level values are shown only when authoritative.</div><div id="providerQuotas"></div></section><section class="card section"><div class="section-title">Recent alerts</div><div id="alerts"></div></section><section class="card section"><div class="section-title">Useful signals</div><div class="small" style="margin-top:9px">• Manual merge/operator gates are highlighted in amber.<br>• Failovers/escalations reveal model instability before a block.<br>• Changed-files vs budget catches scope growth early.<br>• Test/tool-call usage shows verification pressure.<br>• Pending notification count reveals Telegram/outbox delivery lag.</div></section></aside></div><div class="foot">Read-only dashboard. No prompts, raw agent output, credentials, proofs, or protected runtime contents are exposed.</div></div>
<script>
const $=s=>document.querySelector(s);let snapshot=null;let selected=null;const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const fmt=n=>Intl.NumberFormat('en',{notation:Number(n)>=1e6?'compact':'standard',maximumFractionDigits:1}).format(Number(n||0));const pct=(a,b)=>b?Math.min(100,Math.round(a/b*100)):0;const status=s=>`<span class="status s-${esc(s)}">${esc(s||'unknown')}</span>`;
function showLogin(msg=''){ $('#login').classList.add('show');$('#loginErr').textContent=msg }function hideLogin(){ $('#login').classList.remove('show');$('#loginErr').textContent='' }async function login(){const token=$('#token').value;$('#loginErr').textContent='';const r=await fetch('/v1/dashboard/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})});if(!r.ok){showLogin(r.status===503?'Dashboard token is not configured in Runtime.':'Invalid dashboard token.');return}$('#token').value='';hideLogin();await refresh()}$('#loginBtn').onclick=login;$('#token').addEventListener('keydown',e=>{if(e.key==='Enter')login()});
function summaryCards(s){const data=[['Active plans',s.active_plans,'orchestrated'],['Active jobs',s.active_jobs,'model/runtime'],['Merge gates',s.waiting_merge,'manual'],['Human gates',s.waiting_human,'operator/decision'],['Blocked plans',s.blocked_plans,'attention'],['Outbox pending',s.pending_notifications,'notifications']];$('#summary').innerHTML=data.map(x=>`<div class="card"><div class="k">${x[0]}</div><div class="v">${fmt(x[1])}</div><div class="small">${x[2]}</div></div>`).join('')}
function currentPlan(){if(!snapshot?.plans?.length)return null;return snapshot.plans.find(p=>p.id===selected)||snapshot.plans.find(p=>p.id===snapshot.current_plan_id)||snapshot.plans[0]}function currentWO(p){return p?.work_orders?.find(w=>['running','awaiting_merge','waiting_human'].includes(w.state))||p?.work_orders?.find(w=>w.job&&['blocked','failed','interrupted'].includes(w.job.status))||null}
function renderPlanPicker(){const ps=snapshot.plans||[];if(!selected)selected=snapshot.current_plan_id||ps[0]?.id||null;$('#planSelect').innerHTML=ps.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.id)} · ${esc(p.status)}</option>`).join('');$('#planSelect').onchange=e=>{selected=e.target.value;render()}}
function renderPipeline(p){if(!p){$('#pipeline').innerHTML='<div class="empty">No orchestrated plans yet.</div>';$('#planMeta').textContent='—';return}$('#planMeta').innerHTML=`${esc(p.project_id)} · ${esc(p.ticket_id||'')} · ${status(p.status)} · baseline ${esc(p.baseline_revision||'—')}`;$('#pipeline').innerHTML=(p.work_orders||[]).map((w,i)=>`<div class="step ${p.current_work_order_id===w.id?'current':''}"><div class="num">STEP ${i+1} · ${esc(w.execution_mode)}</div><div class="name">${esc(w.id)}</div>${status(w.state)}${w.pr_url?`<div class="small" style="margin-top:8px"><a target="_blank" href="${esc(w.pr_url)}">PR #${esc(w.pr_number||'')}</a></div>`:''}</div>`).join('')}
function metric(label,val,sub,used,max){const p=max?pct(used,max):null;return `<div class="metric"><div class="k">${label}</div><div class="mv">${esc(val)}</div><div class="small">${esc(sub||'')}</div>${p!==null?`<div class="bar"><div class="fill ${p>=90?'danger':p>=70?'warn':''}" style="width:${p}%"></div></div>`:''}</div>`}
function renderJob(w){const j=w?.job;if(!j){$('#jobMeta').textContent=w?`Waiting at ${w.state}`:'No active WorkOrder';$('#jobStatus').innerHTML=w?status(w.state):'';$('#metrics').innerHTML='<div class="empty">No running agent job for this step.</div>';$('#models').innerHTML='<div class="empty">Model assignment unavailable.</div>';$('#tokens').innerHTML='<div class="empty">No job token telemetry.</div>';$('#remaining').innerHTML='<div class="empty">No job budget available.</div>';$('#profile').innerHTML='';return}$('#jobMeta').textContent=`${j.id} · ${w.id} · ${j.branch||'branch pending'}`;$('#jobStatus').innerHTML=status(j.status);const p=j.progress||{},b=j.budget||{};$('#metrics').innerHTML=[metric('Elapsed',`${Number(p.elapsed_minutes||0).toFixed(1)}m`,`budget ${b.max_wall_time_minutes||'—'}m`,p.elapsed_minutes,b.max_wall_time_minutes),metric('Model calls',p.model_calls||0,`iterations ${p.iteration||0}`,p.model_calls,b.max_model_calls),metric('Tool calls',p.tool_calls||0,`tests ${p.test_runs||0}`,p.tool_calls,b.max_tool_calls),metric('Changed files',p.changed_files||0,`limit ${b.max_changed_files||'—'}`,p.changed_files,b.max_changed_files),metric('Repairs',p.repair_iterations||0,`limit ${b.max_repair_iterations||'—'}`,p.repair_iterations,b.max_repair_iterations),metric('Failovers',`${p.provider_failovers||0}/${p.model_failovers||0}`,'provider / model'),metric('Escalations',p.escalations||0,'model / reasoning'),metric('Checks',p.required_checks_passed?'PASS':p.tests_passed?'tests pass':'pending',p.agent_succeeded?'agent succeeded':'agent pending')].join('');const models=j.models||{};$('#profile').innerHTML=`${status(j.profile||'unknown')} <span class="pill">analysis depth ${esc(j.analysis_depth??'—')}</span>${models.current?.reasoning_effort?` <span class="pill">reasoning ${esc(models.current.reasoning_effort)}</span>`:''}`;$('#models').innerHTML=['planner','executor','evaluator'].map(role=>{const m=models[role];return `<div class="model ${models.current&&m&&models.current.id===m.id?'active':''}"><div class="role">${role}${models.current&&m&&models.current.id===m.id?' · current':''}</div><div class="mid">${esc(m?.id||'—')}</div><div class="prov">${esc(m?.provider||'')} ${m?.model?`· ${esc(m.model)}`:''}${m?.reasoning_effort?` · reasoning ${esc(m.reasoning_effort)}`:''}</div></div>`}).join('');const t=j.tokens||{};const inputP=pct(t.input_budget_tokens,t.max_input_tokens),outputP=pct(t.output_tokens,t.max_output_tokens);$('#tokens').innerHTML=`<div class="token-box"><div class="k">Input budget-bearing</div><div class="token-big">${fmt(t.input_budget_tokens)} / ${fmt(t.max_input_tokens)}</div><div class="token-meta">last attempt gross ${fmt(t.last_attempt_gross_input_tokens)} · cached ${fmt(t.last_attempt_cached_input_tokens)} · ${inputP}% budget</div><div class="bar"><div class="fill ${inputP>=90?'danger':inputP>=70?'warn':''}" style="width:${inputP}%"></div></div></div><div class="token-box"><div class="k">Output</div><div class="token-big">${fmt(t.output_tokens)} / ${fmt(t.max_output_tokens)}</div><div class="token-meta">${outputP}% output budget</div><div class="bar"><div class="fill ${outputP>=90?'danger':outputP>=70?'warn':''}" style="width:${outputP}%"></div></div></div>`;const rem=j.remaining||{};$('#remaining').innerHTML=[metric('Input tokens',fmt(rem.input_tokens),'remaining'),metric('Output tokens',fmt(rem.output_tokens),'remaining'),metric('Model calls',rem.model_calls??'—','remaining'),metric('Wall time',rem.wall_time_minutes===null||rem.wall_time_minutes===undefined?'—':`${Number(rem.wall_time_minutes).toFixed(1)}m`,'remaining'),metric('Tool calls',rem.tool_calls??'—','remaining'),metric('Test runs',rem.test_runs??'—','remaining'),metric('Changed files',rem.changed_files??'—','remaining'),metric('Repairs',rem.repair_iterations??'—','remaining')].join('')}
function activityDetail(e){const d=e.data||{};if(e.event==='route_selected'){return ['planner','executor','evaluator'].map(role=>d[role]?.id?`${role} ${d[role].id}${d[role].reasoning_effort?' · '+d[role].reasoning_effort:''}`:'').filter(Boolean).join(' · ')}if(d.from_status&&d.to_status)return `${d.from_status} → ${d.to_status}`;return ''}
function renderActivity(w){const events=w?.job?.recent_events||[];$('#activity').innerHTML=events.length?events.map(e=>`<div class="activity-item"><span class="activity-dot ${esc(e.level)}"></span><div class="activity-message">${esc(e.message)}</div><div class="activity-time">${esc(new Date(e.timestamp).toLocaleTimeString())} · ${esc(e.phase)}</div>${activityDetail(e)?`<div class="activity-detail">${esc(activityDetail(e))}</div>`:''}</div>`).join(''):'<div class="empty">No activity recorded for this job yet.</div>'}
function renderProviderQuotas(){const groups=snapshot.provider_quotas||[];$('#providerQuotas').innerHTML=groups.length?groups.map(q=>`<div class="quota-card"><div class="quota-label">${esc(q.label)}</div><div class="quota-value">${q.remaining_status==='available'?esc(q.remaining):'Unavailable'}</div><div class="small">${esc(q.message)}</div><div class="quota-models">${(q.models||[]).map(esc).join(' · ')}</div></div>`).join(''):'<div class="empty">No quota groups configured.</div>'}
function renderAlerts(){const as=snapshot.alerts||[];$('#alerts').innerHTML=as.length?as.map(a=>`<div class="alert"><div class="alert-top"><span class="sev sev-${esc(a.severity)}">${esc(a.event_type)}</span>${status(a.status)}</div><p>${esc(a.summary)}</p><div class="small">${esc(a.project_id)} ${a.work_order_id?'· '+esc(a.work_order_id):''}</div></div>`).join(''):'<div class="empty">No notifications yet.</div>'}
function render(){summaryCards(snapshot.summary||{});renderPlanPicker();const p=currentPlan(),w=currentWO(p);renderPipeline(p);renderJob(w);renderActivity(w);renderProviderQuotas();renderAlerts();$('#subtitle').textContent=`Updated ${new Date(snapshot.generated_at).toLocaleTimeString()} · ${snapshot.plans?.length||0} plans in view`}async function refresh(){try{const r=await fetch('/v1/dashboard/snapshot',{cache:'no-store'});if(r.status===401){showLogin();return}if(r.status===503){showLogin('Dashboard token is not configured in Runtime.');return}if(!r.ok)throw new Error(`HTTP ${r.status}`);snapshot=await r.json();hideLogin();render();$('#connection').textContent='live · polling every 3s'}catch(e){$('#connection').textContent='disconnected';console.error(e)}}refresh();setInterval(refresh,3000);
</script>
</body></html>'''


